jobs := make(chan Job, 8)
var wg sync.WaitGroup
for i := 0; i < 4; i++ {
    wg.Add(1)
    go func() { defer wg.Done()
        for j := range jobs {        // drains, then ends on close
            process(j)
        }
    }()
}
// ... all work is sent into jobs ...
close(jobs)                          // the pill, for every consumer at once
wg.Wait()
